/**
 * Stripe Tax registrations helpers — Sprint 19.
 *
 * Server-side only. Never import from client components.
 *
 * Every Stripe SDK call goes through withIdempotencyKey() (INVARIANT 2).
 * INVARIANT 7: This module is Stripe-only. Never import from lib/dodo/*.
 */
import type { SupabaseClient } from '@supabase/supabase-js'
import { getStripe } from './client'
import { idempotencyKeyFor, withIdempotencyKey } from './idempotency'
import {
  RPC,
  type StripeTaxRegistrationStatus,
  type StripeTaxRegistrationRecordArgs,
  type StripeTaxRegistrationRecordResult,
  type StripeTaxRegistrationRemoveArgs,
  type StripeTaxRegistrationRemoveResult,
} from '@/lib/payments/contracts'
import { logger } from '@/lib/logger'

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Derive canonical jurisdiction string from country + optional state.
 * Mirrors the DB `jurisdiction` column convention used in tax_remittance_ledger.
 */
function buildJurisdiction(country: string, state: string | null): string {
  if (state) {
    return `${country.toUpperCase()}-${state.toUpperCase()}`
  }
  return country.toUpperCase()
}

/**
 * Map Stripe registration active_from / expires_at to our status enum.
 * Stripe's status field uses 'active' | 'expired' | 'scheduled' — same as ours.
 * We accept the Stripe string and validate against our type.
 */
function coerceRegistrationStatus(
  stripeStatus: string,
): StripeTaxRegistrationStatus {
  if (
    stripeStatus === 'active' ||
    stripeStatus === 'expired' ||
    stripeStatus === 'scheduled'
  ) {
    return stripeStatus
  }
  // Unknown future Stripe status — treat as active (least disruptive)
  logger.warn({ stripeStatus }, 'stripe tax: unknown registration status — defaulting to active')
  return 'active'
}

// ---------------------------------------------------------------------------
// createStripeTaxRegistration
// ---------------------------------------------------------------------------

export interface CreateStripeTaxRegistrationArgs {
  connectedAccountId: string
  country: string
  /** Required for US registrations (state code e.g. 'NY'). Null for non-US. */
  state: string | null
  /** Unix seconds. Default to now if 0. */
  activeFromUnixSec: number
}

export interface CreateStripeTaxRegistrationResult {
  registrationId: string
  jurisdiction: string
  status: StripeTaxRegistrationStatus
}

/**
 * Create a Stripe Tax registration on the connected account, then record it
 * in the DB via the STRIPE_TAX_REGISTRATION_RECORD RPC.
 *
 * The studioId parameter is the InkOS studio UUID (for DB ownership).
 * The connectedAccountId is the Stripe acct_xxx.
 */
export async function createStripeTaxRegistration(
  supabase: SupabaseClient,
  studioId: string,
  args: CreateStripeTaxRegistrationArgs,
): Promise<CreateStripeTaxRegistrationResult> {
  const stripe = getStripe()

  const idemKey = idempotencyKeyFor('tax.registration.create', {
    connected_account_id: args.connectedAccountId,
    country: args.country,
    state: args.state ?? '',
    active_from: args.activeFromUnixSec,
  })

  const activeFrom = args.activeFromUnixSec > 0
    ? args.activeFromUnixSec
    : Math.floor(Date.now() / 1000)

  // Stripe requires at minimum { country } + { type: 'simplified' | ... } depending on country.
  // For the US we pass state_sales_tax with state. For all other countries we use 'standard'.
  // The discriminated union in the Stripe SDK requires correct nesting per country.
  type RegistrationParams = Parameters<typeof stripe.tax.registrations.create>[0]

  let countryOptions: RegistrationParams['country_options']
  const upperCountry = args.country.toUpperCase()

  if (upperCountry === 'US' && args.state) {
    countryOptions = {
      us: {
        state: args.state.toUpperCase(),
        type: 'state_sales_tax',
      },
    }
  } else if (upperCountry === 'GB') {
    countryOptions = { gb: { type: 'standard' } }
  } else if (upperCountry === 'AU') {
    countryOptions = { au: { type: 'standard' } }
  } else if (upperCountry === 'CA' && args.state) {
    countryOptions = {
      ca: {
        province_standard: { province: args.state.toUpperCase() },
        type: 'province_standard',
      },
    }
  } else if (upperCountry === 'CA') {
    countryOptions = { ca: { type: 'gst_hst' } }
  } else {
    // EU + remaining countries: use country code as lowercase key + standard type
    const lcCountry = upperCountry.toLowerCase() as keyof RegistrationParams['country_options'] & string
    countryOptions = { [lcCountry]: { type: 'standard' } } as RegistrationParams['country_options']
  }

  const registration = await withIdempotencyKey(idemKey, (key) =>
    stripe.tax.registrations.create(
      {
        country: upperCountry,
        country_options: countryOptions,
        active_from: activeFrom,
      },
      {
        stripeAccount: args.connectedAccountId,
        idempotencyKey: key,
      },
    ),
  )

  const jurisdiction = buildJurisdiction(args.country, args.state)
  const status = coerceRegistrationStatus(registration.status)

  logger.info(
    {
      registrationId: registration.id,
      connectedAccountId: args.connectedAccountId,
      jurisdiction,
      status,
    },
    'stripe tax: registration created',
  )

  // Mirror to DB
  const rpcArgs: StripeTaxRegistrationRecordArgs = {
    studioId,
    registrationId: registration.id,
    country: upperCountry,
    state: args.state ? args.state.toUpperCase() : null,
    jurisdiction,
    status,
    activeFrom: new Date(activeFrom * 1000).toISOString(),
    activeUntil: registration.expires_at
      ? new Date(registration.expires_at * 1000).toISOString()
      : null,
  }

  const { data, error } = await supabase.rpc(RPC.STRIPE_TAX_REGISTRATION_RECORD, {
    p_studio_id: rpcArgs.studioId,
    p_registration_id: rpcArgs.registrationId,
    p_country: rpcArgs.country,
    p_state: rpcArgs.state,
    p_jurisdiction: rpcArgs.jurisdiction,
    p_status: rpcArgs.status,
    p_active_from: rpcArgs.activeFrom,
    p_active_until: rpcArgs.activeUntil,
  })

  if (error) {
    logger.error(
      { err: error, registrationId: registration.id, studioId },
      'stripe tax: failed to record registration via RPC',
    )
    throw error
  }

  // §S13.3 — types.ts regen pending; RPC result shape confirmed by Dato
  const result = data as StripeTaxRegistrationRecordResult
  logger.info({ rowId: result.id, created: result.created, registrationId: registration.id }, 'stripe tax: registration mirrored to DB')

  return { registrationId: registration.id, jurisdiction, status }
}

// ---------------------------------------------------------------------------
// expireStripeTaxRegistration
// ---------------------------------------------------------------------------

export interface ExpireStripeTaxRegistrationArgs {
  connectedAccountId: string
  registrationId: string
}

export interface ExpireStripeTaxRegistrationResult {
  registrationId: string
  status: StripeTaxRegistrationStatus
}

/**
 * Expire a Stripe Tax registration on the connected account.
 * "Expiring" sets expires_at to now, which deactivates tax collection.
 * We do NOT delete registrations — Stripe retains them for audit history.
 */
export async function expireStripeTaxRegistration(
  args: ExpireStripeTaxRegistrationArgs,
): Promise<ExpireStripeTaxRegistrationResult> {
  const stripe = getStripe()

  const updated = await stripe.tax.registrations.update(
    args.registrationId,
    { expires_at: 'now' },
    { stripeAccount: args.connectedAccountId },
  )

  const status = coerceRegistrationStatus(updated.status)

  logger.info(
    { registrationId: args.registrationId, connectedAccountId: args.connectedAccountId, status },
    'stripe tax: registration expired',
  )

  return { registrationId: args.registrationId, status }
}

// ---------------------------------------------------------------------------
// syncStripeTaxRegistrations
// ---------------------------------------------------------------------------

/**
 * Fetch all tax registrations from Stripe for the given connected account and
 * mirror each one to the DB via STRIPE_TAX_REGISTRATION_RECORD.
 *
 * Idempotent: the RPC uses ON CONFLICT DO UPDATE for status/dates.
 * Suitable for the POST /sync endpoint and for reconciliation cron.
 *
 * Returns the full list of registrations after sync.
 */
export async function syncStripeTaxRegistrations(
  supabase: SupabaseClient,
  studioId: string,
  connectedAccountId: string,
): Promise<StripeTaxRegistrationRecordArgs[]> {
  const stripe = getStripe()

  const list = await stripe.tax.registrations.list(
    { status: 'all', limit: 100 },
    { stripeAccount: connectedAccountId },
  )

  const synced: StripeTaxRegistrationRecordArgs[] = []

  for (const reg of list.data) {
    // Extract country and state from the registration's country_options
    // The first key of country_options is the country code
    const countryKey = Object.keys(reg.country_options ?? {})[0] ?? ''
    const upperCountry = countryKey.toUpperCase()

    // Try to extract state from US country_options
    let state: string | null = null
    const countryOpts = reg.country_options as Record<string, Record<string, string | undefined> | undefined> | undefined
    if (upperCountry === 'US' && countryOpts?.us?.state) {
      state = countryOpts.us.state
    } else if (upperCountry === 'CA') {
      const caOpts = countryOpts?.ca as Record<string, unknown> | undefined
      const provStd = caOpts?.province_standard as Record<string, string> | undefined
      if (provStd?.province) {
        state = provStd.province
      }
    }

    const jurisdiction = buildJurisdiction(upperCountry || reg.country, state)
    const status = coerceRegistrationStatus(reg.status)

    const rpcArgs: StripeTaxRegistrationRecordArgs = {
      studioId,
      registrationId: reg.id,
      country: upperCountry || reg.country,
      state,
      jurisdiction,
      status,
      activeFrom: new Date(reg.active_from * 1000).toISOString(),
      activeUntil: reg.expires_at
        ? new Date(reg.expires_at * 1000).toISOString()
        : null,
    }

    const { error } = await supabase.rpc(RPC.STRIPE_TAX_REGISTRATION_RECORD, {
      p_studio_id: rpcArgs.studioId,
      p_registration_id: rpcArgs.registrationId,
      p_country: rpcArgs.country,
      p_state: rpcArgs.state,
      p_jurisdiction: rpcArgs.jurisdiction,
      p_status: rpcArgs.status,
      p_active_from: rpcArgs.activeFrom,
      p_active_until: rpcArgs.activeUntil,
    })

    if (error) {
      logger.error(
        { err: error, registrationId: reg.id, studioId },
        'stripe tax: sync failed for registration',
      )
      // Continue with remaining registrations
      continue
    }

    synced.push(rpcArgs)
  }

  logger.info(
    { studioId, connectedAccountId, count: synced.length, total: list.data.length },
    'stripe tax: registration sync complete',
  )

  return synced
}

/**
 * GET  /api/settings/payments/tax-registrations  — list studio's tax registrations
 * POST /api/settings/payments/tax-registrations  — add a new registration via Stripe
 */
import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { createStripeTaxRegistration } from '@/lib/stripe/tax-registrations'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

// ---------------------------------------------------------------------------
// POST body schema
// ---------------------------------------------------------------------------

const PostBodySchema = z.object({
  country: z.string().length(2, 'Country must be a two-letter ISO 3166 code.').toUpperCase(),
  state: z.string().min(1).max(10).toUpperCase().optional(),
  /** ISO date string e.g. '2026-05-01'. Defaults to today when absent. */
  activeFromIso: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'activeFromIso must be YYYY-MM-DD.').optional(),
})

// ---------------------------------------------------------------------------
// GET
// ---------------------------------------------------------------------------

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'Too many requests.' }, { status: 429 })
  }

  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 })
  }

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'Owner or admin role required.' }, { status: 403 })
  }

  const supabase = await createClient()

  // RLS on stripe_tax_registrations ensures studio_id scoping
  const { data: registrations, error } = await supabase
    .from('stripe_tax_registrations')
    .select('*')
    .eq('studio_id', auth.studioId)
    .order('active_from', { ascending: false })

  if (error) {
    logger.error({ err: error, studioId: auth.studioId }, 'tax-registrations GET: query failed')
    return NextResponse.json({ error: 'Could not load tax registrations.' }, { status: 500 })
  }

  return NextResponse.json({ registrations: registrations ?? [] })
}

// ---------------------------------------------------------------------------
// POST
// ---------------------------------------------------------------------------

export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'Too many requests.' }, { status: 429 })
  }

  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 })
  }

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'Owner or admin role required.' }, { status: 403 })
  }

  let body: z.infer<typeof PostBodySchema>
  try {
    const raw: unknown = await req.json()
    body = PostBodySchema.parse(raw)
  } catch (err) {
    const message = err instanceof z.ZodError
      ? err.errors.map((e) => e.message).join(' ')
      : 'Invalid request body.'
    return NextResponse.json({ error: message }, { status: 400 })
  }

  const supabase = await createClient()

  // Resolve the studio's connected account id
  const { data: accountRow, error: accountError } = await supabase
    .from('stripe_connected_accounts')
    .select('account_id')
    .eq('studio_id', auth.studioId)
    .eq('type', 'studio')
    .eq('onboarding_status', 'active')
    .single()

  if (accountError || !accountRow) {
    return NextResponse.json(
      { error: 'No active connected account found for this studio.' },
      { status: 422 },
    )
  }

  // §S13.3
  const connectedAccountRow = accountRow as { account_id: string }

  const activeFromUnixSec = body.activeFromIso
    ? Math.floor(new Date(body.activeFromIso).getTime() / 1000)
    : Math.floor(Date.now() / 1000)

  try {
    const result = await createStripeTaxRegistration(supabase, auth.studioId, {
      connectedAccountId: connectedAccountRow.account_id,
      country: body.country,
      state: body.state ?? null,
      activeFromUnixSec,
    })

    await logAuditAction(
      auth.user.id,
      'tax_registration_added',
      { type: 'stripe_tax_registration', id: result.registrationId },
      { jurisdiction: result.jurisdiction, status: result.status },
      auth.studioId,
    )

    return NextResponse.json({ registration_id: result.registrationId }, { status: 201 })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'tax-registrations POST: create failed')
    return NextResponse.json(
      { error: 'Could not create tax registration. Check the country and state.' },
      { status: 500 },
    )
  }
}

/**
 * DELETE /api/settings/payments/tax-registrations/[id]  — expire a registration
 */
import { NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { expireStripeTaxRegistration } from '@/lib/stripe/tax-registrations'
import { RPC, type StripeTaxRegistrationRemoveArgs } from '@/lib/payments/contracts'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function DELETE(req: NextRequest, context: RouteContext) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'Too many requests.' }, { status: 429 })
  }

  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 })
  }

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'Owner or admin role required.' }, { status: 403 })
  }

  const { id: registrationId } = await context.params

  const supabase = await createClient()

  // Resolve connected account — must be active
  const { data: accountRow, error: accountError } = await supabase
    .from('stripe_connected_accounts')
    .select('account_id')
    .eq('studio_id', auth.studioId)
    .eq('type', 'studio')
    .eq('onboarding_status', 'active')
    .single()

  if (accountError || !accountRow) {
    return NextResponse.json(
      { error: 'No active connected account found for this studio.' },
      { status: 422 },
    )
  }

  // §S13.3
  const connectedAccountRow = accountRow as { account_id: string }

  // Verify the registration belongs to this studio (RLS check via session client)
  const { data: regRow, error: regError } = await supabase
    .from('stripe_tax_registrations')
    .select('id, registration_id')
    .eq('studio_id', auth.studioId)
    .eq('registration_id', registrationId)
    .single()

  if (regError || !regRow) {
    return NextResponse.json({ error: 'Tax registration not found.' }, { status: 404 })
  }

  // §S13.3
  const typedRegRow = regRow as { id: string; registration_id: string }

  try {
    // Expire on Stripe
    const expireResult = await expireStripeTaxRegistration({
      connectedAccountId: connectedAccountRow.account_id,
      registrationId,
    })

    // Remove from DB via RPC
    const rpcArgs: StripeTaxRegistrationRemoveArgs = {
      studioId: auth.studioId,
      registrationId,
    }

    const { error: rpcError } = await supabase.rpc(RPC.STRIPE_TAX_REGISTRATION_REMOVE, {
      p_studio_id: rpcArgs.studioId,
      p_registration_id: rpcArgs.registrationId,
    })

    if (rpcError) {
      logger.error(
        { err: rpcError, registrationId, studioId: auth.studioId },
        'tax-registrations DELETE: RPC remove failed',
      )
      return NextResponse.json({ error: 'Could not remove tax registration from records.' }, { status: 500 })
    }

    await logAuditAction(
      auth.user.id,
      'tax_registration_removed',
      { type: 'stripe_tax_registration', id: typedRegRow.id },
      { registration_id: registrationId, status: expireResult.status },
      auth.studioId,
    )

    return NextResponse.json({ id: registrationId, status: 'expired' })
  } catch (err) {
    logger.error({ err, registrationId, studioId: auth.studioId }, 'tax-registrations DELETE: expire failed')
    return NextResponse.json(
      { error: 'Could not expire the tax registration.' },
      { status: 500 },
    )
  }
}

/**
 * POST /api/settings/payments/tax-registrations/sync
 *
 * Pull all tax registrations from Stripe and mirror them to the DB.
 * Idempotent — safe to call repeatedly. Used by the "Refresh from Stripe" button.
 */
import { NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { syncStripeTaxRegistrations } from '@/lib/stripe/tax-registrations'
import { logger } from '@/lib/logger'

export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await expensiveRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'Too many requests.' }, { status: 429 })
  }

  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 })
  }

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'Owner or admin role required.' }, { status: 403 })
  }

  const supabase = await createClient()

  const { data: accountRow, error: accountError } = await supabase
    .from('stripe_connected_accounts')
    .select('account_id')
    .eq('studio_id', auth.studioId)
    .eq('type', 'studio')
    .eq('onboarding_status', 'active')
    .single()

  if (accountError || !accountRow) {
    return NextResponse.json(
      { error: 'No active connected account found for this studio.' },
      { status: 422 },
    )
  }

  // §S13.3
  const connectedAccountRow = accountRow as { account_id: string }

  try {
    const registrations = await syncStripeTaxRegistrations(
      supabase,
      auth.studioId,
      connectedAccountRow.account_id,
    )

    return NextResponse.json({
      registrations,
      synced_at: new Date().toISOString(),
    })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'tax-registrations sync: failed')
    return NextResponse.json(
      { error: 'Could not sync tax registrations from Stripe.' },
      { status: 500 },
    )
  }
}

'use client'

/**
 * TaxRegistrationsList
 *
 * Owner/admin view — list, add, and remove Stripe Tax registrations.
 * Brand: Bone/Onyx/Stone/Rust tokens only. Editorial voice. No exclamations.
 */

import { useEffect, useState, useCallback } from 'react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import {
  Select,
  SelectContent,
