  { code: 'SD', label: 'South Dakota' }, { code: 'TN', label: 'Tennessee' },
  { code: 'TX', label: 'Texas' }, { code: 'UT', label: 'Utah' },
  { code: 'VT', label: 'Vermont' }, { code: 'VA', label: 'Virginia' },
  { code: 'WA', label: 'Washington' }, { code: 'WV', label: 'West Virginia' },
  { code: 'WI', label: 'Wisconsin' }, { code: 'WY', label: 'Wyoming' },
  { code: 'DC', label: 'District of Columbia' },
] as const

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  })
}

function countryLabel(code: string): string {
  return SUPPORTED_COUNTRIES.find((c) => c.code === code)?.label ?? code
}

// ---------------------------------------------------------------------------
// StatusPill
// ---------------------------------------------------------------------------

interface StatusPillProps {
  status: TaxRegistrationRow['status']
  isFirstExpired: boolean
}

function StatusPill({ status, isFirstExpired }: StatusPillProps) {
  const base = 'inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-semibold uppercase tracking-wide'

  if (status === 'active') {
    return (
      <span className={cn(base, 'bg-foreground/8 text-foreground')}>
        Active
      </span>
    )
  }

  if (status === 'expired') {
    return (
      <span
        className={cn(
          base,
          // Rust only for the first expired card per viewport
          isFirstExpired
            ? 'bg-destructive/10 text-destructive'
            : 'bg-muted text-muted-foreground',
        )}
      >
        Expired
      </span>
    )
  }

  return (
    <span className={cn(base, 'bg-muted text-muted-foreground')}>
      Scheduled
    </span>
  )
}

// ---------------------------------------------------------------------------
// RegistrationCard
// ---------------------------------------------------------------------------

interface RegistrationCardProps {
  reg: TaxRegistrationRow
  isFirstExpired: boolean
  onRemove: (registrationId: string) => Promise<void>
  isRemoving: boolean
}

function RegistrationCard({ reg, isFirstExpired, onRemove, isRemoving }: RegistrationCardProps) {
  return (
    <div className="flex items-start justify-between gap-4 rounded-xl border border-border/60 bg-card p-5 shadow-[var(--shadow-soft)]">
      <div className="space-y-1 min-w-0">
        {/* Jurisdiction code */}
        <p className="text-[15px] font-semibold text-foreground font-mono tabular-nums">
          {reg.jurisdiction}
        </p>

        {/* Country / state details */}
        <p className="text-xs text-muted-foreground">
          {reg.state ? `${countryLabel(reg.country)} — ${reg.state}` : countryLabel(reg.country)}
        </p>

        {/* Dates */}
        <p className="text-[11px] text-muted-foreground tabular-nums">
          Active from {formatDate(reg.active_from)}
          {reg.active_until ? ` · expires ${formatDate(reg.active_until)}` : ''}
        </p>
      </div>

      <div className="flex shrink-0 items-center gap-3">
        <StatusPill status={reg.status} isFirstExpired={isFirstExpired} />

        {reg.status !== 'expired' && (
          <Button
            variant="ghost"
            size="sm"
            disabled={isRemoving}
            onClick={() => void onRemove(reg.registration_id)}
            className="text-muted-foreground hover:text-foreground"
          >
            {isRemoving ? 'Removing…' : 'Remove'}
          </Button>
        )}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// AddRegistrationDialog
// ---------------------------------------------------------------------------

interface AddRegistrationDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onAdded: () => void
}

function AddRegistrationDialog({ open, onOpenChange, onAdded }: AddRegistrationDialogProps) {
  const [country, setCountry] = useState<string>('')
  const [state, setState] = useState<string>('')
  const [activeFromIso, setActiveFromIso] = useState<string>(
    new Date().toISOString().slice(0, 10),
  )
  const [isSaving, setIsSaving] = useState(false)

  const isUS = country === 'US'

  async function handleAdd() {
    if (!country) {
      toast.error('Select a country.')
      return
    }
    if (isUS && !state) {
      toast.error('Select a state for US registrations.')
      return
    }

    setIsSaving(true)
    try {
      const res = await fetch('/api/settings/payments/tax-registrations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          country,
          state: isUS ? state : undefined,
          activeFromIso,
        }),
      })

      if (!res.ok) {
        const json = (await res.json()) as { error?: string }
        toast.error(json.error ?? 'Could not add tax registration.')
        return
      }

      toast('Tax registration added.')
      onOpenChange(false)
      onAdded()
      setCountry('')
      setState('')
      setActiveFromIso(new Date().toISOString().slice(0, 10))
    } catch {
      toast.error('Check your connection and try again.')
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="font-serif italic font-normal text-[18px]">
            Add tax registration
          </DialogTitle>
          <DialogDescription className="text-xs text-muted-foreground">
            Register a jurisdiction where your studio collects sales tax.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Country */}
          <div className="space-y-1.5">
            <Label htmlFor="tax-country" className="text-[11px] font-bold uppercase tracking-wide text-muted-foreground">
              Country
            </Label>
            <Select value={country} onValueChange={(v) => { setCountry(v); setState('') }}>
              <SelectTrigger id="tax-country">
                <SelectValue placeholder="Select country" />
              </SelectTrigger>
              <SelectContent>
                {SUPPORTED_COUNTRIES.map((c) => (
                  <SelectItem key={c.code} value={c.code}>
                    {c.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* State — US only */}
          {isUS && (
            <div className="space-y-1.5">
              <Label htmlFor="tax-state" className="text-[11px] font-bold uppercase tracking-wide text-muted-foreground">
                State
              </Label>
              <Select value={state} onValueChange={setState}>
                <SelectTrigger id="tax-state">
                  <SelectValue placeholder="Select state" />
                </SelectTrigger>
                <SelectContent>
                  {US_STATES.map((s) => (
                    <SelectItem key={s.code} value={s.code}>
                      {s.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Active from */}
          <div className="space-y-1.5">
            <Label htmlFor="tax-active-from" className="text-[11px] font-bold uppercase tracking-wide text-muted-foreground">
              Active from
            </Label>
            <Input
              id="tax-active-from"
              type="date"
              value={activeFromIso}
              onChange={(e) => setActiveFromIso(e.target.value)}
              className="tabular-nums"
            />
          </div>
        </div>

        <DialogFooter>
          <Button
            variant="ghost"
            onClick={() => onOpenChange(false)}
            disabled={isSaving}
          >
            Cancel
          </Button>
          <Button
            onClick={() => void handleAdd()}
            disabled={isSaving || !country || (isUS && !state)}
          >
            {isSaving ? 'Adding…' : 'Add registration'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ---------------------------------------------------------------------------
// TaxRegistrationsList (main export)
// ---------------------------------------------------------------------------

export function TaxRegistrationsList() {
  const [registrations, setRegistrations] = useState<TaxRegistrationRow[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isRefreshing, setIsRefreshing] = useState(false)
  const [removingId, setRemovingId] = useState<string | null>(null)
  const [dialogOpen, setDialogOpen] = useState(false)

  const load = useCallback(async () => {
    setIsLoading(true)
    try {
      const res = await fetch('/api/settings/payments/tax-registrations')
      if (!res.ok) {
        toast.error('Could not load tax registrations.')
        return
      }
      const json = (await res.json()) as { registrations: TaxRegistrationRow[] }
      setRegistrations(json.registrations)
    } catch {
      toast.error('Check your connection and try again.')
    } finally {
      setIsLoading(false)
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  async function handleRefresh() {
    setIsRefreshing(true)
    try {
      const res = await fetch('/api/settings/payments/tax-registrations/sync', {
        method: 'POST',
      })
      if (!res.ok) {
        const json = (await res.json()) as { error?: string }
        toast.error(json.error ?? 'Could not sync from Stripe.')
        return
      }
      toast('Registrations refreshed from Stripe.')
      await load()
    } catch {
      toast.error('Check your connection and try again.')
    } finally {
      setIsRefreshing(false)
    }
  }

  async function handleRemove(registrationId: string) {
    setRemovingId(registrationId)
    try {
      const res = await fetch(
        `/api/settings/payments/tax-registrations/${registrationId}`,
        { method: 'DELETE' },
      )
      if (!res.ok) {
        const json = (await res.json()) as { error?: string }
        toast.error(json.error ?? 'Could not remove the registration.')
        return
      }
      toast('Tax registration removed.')
      await load()
    } catch {
      toast.error('Check your connection and try again.')
    } finally {
      setRemovingId(null)
    }
  }

  // Track which is the first expired card for the Rust accent rule
  let firstExpiredFound = false

  return (
    <>
      {/* Toolbar */}
      <div className="mb-5 flex items-center justify-between gap-3">
        <p className="text-xs text-muted-foreground tabular-nums">
          {isLoading
            ? 'Loading…'
            : `${registrations.length} registration${registrations.length !== 1 ? 's' : ''}`}
        </p>

        <div className="flex items-center gap-2">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => void handleRefresh()}
            disabled={isRefreshing || isLoading}
          >
            {isRefreshing ? 'Refreshing…' : 'Refresh from Stripe'}
          </Button>
          <Button
            size="sm"
            onClick={() => setDialogOpen(true)}
          >
            Add registration
          </Button>
        </div>
      </div>

      {/* List */}
      {isLoading ? (
        <div className="space-y-3">
          {[0, 1, 2].map((i) => (
            <div
              key={i}
              className="h-[72px] rounded-xl border border-border/40 bg-card animate-pulse"
            />
          ))}
        </div>
      ) : registrations.length === 0 ? (
        <div className="rounded-xl border border-border/40 bg-card p-10 text-center shadow-[var(--shadow-soft)]">
          <p className="font-serif italic text-[17px] text-foreground">No registrations yet.</p>
          <p className="mt-1 text-xs text-muted-foreground">
            Add a jurisdiction where your studio collects sales tax.
          </p>
        </div>
      ) : (
        <div className="space-y-3">
          {registrations.map((reg) => {
            const isFirstExpired = reg.status === 'expired' && !firstExpiredFound
            if (isFirstExpired) firstExpiredFound = true

            return (
              <RegistrationCard
                key={reg.id}
                reg={reg}
                isFirstExpired={isFirstExpired}
                onRemove={handleRemove}
                isRemoving={removingId === reg.registration_id}
              />
            )
          })}
        </div>
      )}

      {/* Add dialog */}
      <AddRegistrationDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        onAdded={() => void load()}
      />
    </>
  )
}

